WITH scored AS (SELECT id, store_id, product_id, sale_date, units, revenue, ROW_NUMBER() OVER (ORDER BY revenue DESC, id) AS row_seq, PERCENT_RANK() OVER w_running AS units_percent_rank FROM store_sales WINDOW w_running AS (PARTITION BY product_id, store_id ORDER BY units DESC NULLS LAST)) SELECT id, store_id, sale_date, units, revenue, row_seq, units_percent_rank FROM scored ORDER BY store_id DESC NULLS FIRST;
